import tree_sitter_php as tsp
from tree_sitter import Language, Parser, Query, QueryCursor

LANG = Language(tsp.language_php())
ELEMENT = r"""
(function_definition
  name: (name) @func_name) @function
(method_declaration
  name: (name) @method_name) @function
(class_declaration
  name: (name) @class_name) @class
(interface_declaration
  name: (name) @interface_name) @class
(trait_declaration
  name: (name) @trait_name) @class
(enum_declaration
  name: (name) @enum_name) @class
"""
CALL = r"""
(function_call_expression
  function: (name) @call)
(member_call_expression
  name: (name) @call)
(nullsafe_member_call_expression
  name: (name) @call)
(scoped_call_expression
  name: (name) @call)
"""
IMPORT = r"""
(namespace_use_declaration) @import_path
"""
REFERENCE = r"""
(named_type (name) @type_ref)
"""
DEFUSE = r"""
(assignment_expression
  left: (variable_name (name) @write.assign))
(augmented_assignment_expression
  left: (variable_name (name) @writeread.update))
(update_expression
  argument: (variable_name (name) @writeread.update))
(static_variable_declaration
  name: (variable_name (name) @write.local))
(simple_parameter
  name: (variable_name (name) @write.param))
(variable_name (name) @read.usage)
"""

def parse(src):
    p = Parser(LANG)
    return p.parse(src.encode())

def has_error(node):
    if node.type == "ERROR" or node.is_missing:
        return True
    return any(has_error(c) for c in node.children)

def caps(query_src, src, root):
    q = Query(LANG, query_src)
    out = []
    for _, cd in QueryCursor(q).matches(root):
        for name, nodes in cd.items():
            for n in nodes:
                out.append((name, n.type, src.encode()[n.start_byte:n.end_byte].decode()))
    return q, out

def inherits(class_node, src):
    res = []
    for child in class_node.children:
        if child.type == "base_clause":
            for c in child.named_children:
                if c.type in ("name", "qualified_name", "relative_name"):
                    res.append("extends " + src.encode()[c.start_byte:c.end_byte].decode())
        elif child.type == "class_interface_clause":
            for c in child.named_children:
                if c.type in ("name", "qualified_name", "relative_name"):
                    res.append("implements " + src.encode()[c.start_byte:c.end_byte].decode())
    return res

if __name__ == "__main__":
    import sys
    for label, query in [("ELEMENT", ELEMENT), ("CALL", CALL), ("IMPORT", IMPORT), ("REFERENCE", REFERENCE), ("DEFUSE", DEFUSE)]:
        Query(LANG, query)  # raises on invalid
        print(label, "compiles")
    src = open(sys.argv[1]).read()
    tree = parse(src)
    print("HAS_ERROR", has_error(tree.root_node))
    for label, query in [("ELEMENT", ELEMENT), ("CALL", CALL), ("IMPORT", IMPORT), ("REFERENCE", REFERENCE), ("DEFUSE", DEFUSE)]:
        _, out = caps(query, src, tree.root_node)
        print("==", label, len(out))
        for o in out:
            print("  ", o)
    def walk(n):
        if n.type in ("class_declaration","interface_declaration","enum_declaration","trait_declaration"):
            print("INHERIT", n.type, n.child_by_field_name("name").text.decode(), inherits(n, src))
        for c in n.children:
            walk(c)
    walk(tree.root_node)
EOF
